export class Limiter {
  private hits = new Map<string, number[]>();

  constructor(
    private readonly limit: number,
    private readonly windowMs: number,
  ) {}

  /** Returns 0 when allowed, otherwise the number of ms to wait. */
  check(key: string, now = Date.now()): number {
    const recent = (this.hits.get(key) ?? []).filter((t) => now - t < this.windowMs);
    if (recent.length >= this.limit) {
      this.hits.set(key, recent);
      return this.windowMs - (now - recent[0]!);
    }
    recent.push(now);
    this.hits.set(key, recent);
    return 0;
  }
}

import { createServer } from 'node:http';
import { Limiter } from './limiter.js';

const limiter = new Limiter(60, 60_000);

export const server = createServer((req, res) => {
  const key = String(req.headers['x-api-key'] ?? 'anonymous');
  const wait = limiter.check(key);
  if (wait > 0) {
    res.writeHead(429, { 'Retry-After': String(Math.ceil(wait / 1000)) });
    res.end('rate limited');
    return;
  }
  res.writeHead(200, { 'content-type': 'application/json' });
  res.end(JSON.stringify({ ok: true }));
});
